package com.campusos.backend.controller; import com.campusos.backend.entity.Subject; import com.campusos.backend.service.SubjectService; import org.springframework.web.bind.annotation.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import java.util.List;
@RestController @RequestMapping("/api/subjects") public class SubjectController { private final SubjectService s; public SubjectController(SubjectService s){this.s=s;} @PostMapping public Subject create(@RequestBody Subject x,@AuthenticationPrincipal String email){return s.createSubject(x,email);} @GetMapping public List<Subject> all(){return s.getAllSubjects();} @PutMapping("/{id}") public Subject update(@PathVariable Long id,@RequestBody Subject x,@AuthenticationPrincipal String email){return s.updateSubject(id,x,email);} @DeleteMapping("/{id}") public String delete(@PathVariable Long id,@AuthenticationPrincipal String email){s.deleteSubject(id,email);return "Subject deleted";} }
